#include "sea_map_transition.hpp"
#include <iostream>
#include <stdexcept>
#include <string>
#include <algorithm>
static int assertions=0;
void check(bool b,const char*msg){++assertions;if(!b)throw std::runtime_error(msg);}
bool near(float a,float b){return std::abs(a-b)<.0001f;} bool same(CVECTOR a,CVECTOR b){return near(a.x,b.x)&&near(a.y,b.y)&&near(a.z,b.z);}
int events(const char*n){return std::count(core.actions.begin(),core.actions.end(),n);}
void reset(VDX9RENDER&rs){core=FakeCore{};core.rs=&rs;storm_map_player::metricsAvailable=true;storm_map_player::boundsCalls=storm_map_player::visualCalls=storm_map_player::seaCalls=storm_map_player::prepareCalls=0;storm_map_player::seaPosition={10,3,20};}
void execute(SeaMapTransition&t,float ms){core.dt=ms;t.ProcessStage(Stage::execute,0);} void realize(SeaMapTransition&t){t.ProcessStage(Stage::realize,0);}
ATTRIBUTES attrs(bool seaOnly=false,bool reverse=false){ATTRIBUTES a;a.values={{"seaOnly",seaOnly},{"reverse",reverse},{"x",10},{"y",3},{"z",20},{"mapHeight",200}};return a;}
void seaLifecycle(){VDX9RENDER rs;reset(rs);auto a=attrs(true);storm_map_player::metricsAvailable=false;SeaMapTransition t;t.AttributesPointer=&a;check(t.Init(),"seaOnly Init independent of miniature metrics");check(storm_map_player::boundsCalls==0&&storm_map_player::visualCalls==0,"seaOnly bypasses miniature metrics");
 execute(t,5000);check(rs.cameraSets==0&&rs.lookCameraSets==0&&rs.perspectiveSets==0,"seaOnly does not ascend before capture");check(events("Sea_MapTransitionCommit")==0,"no commit before captured sea frame");
 const CVECTOR oldPosition=rs.position,oldAngles=rs.angles,oldShip=storm_map_player::seaPosition;const float oldFov=rs.fov;realize(t);check(rs.captureCalls==1,"first sea Realize captures once");check(events("Sea_MapTransitionCommit")==0,"capture never commits in Realize");check(SeaMapTransition::Loading(),"loading after capture");
 execute(t,16);check(events("Sea_MapTransitionCommit")==1,"first subsequent Execute commits once");execute(t,16);check(events("Sea_MapTransitionCommit")==1,"second Execute does not duplicate commit");realize(t);check(rs.colors.back()==0xffffffff&&rs.frameTags.back()==17,"opaque outgoing sea frame retained");
 a.values["mapReady"]=1;for(int i=0;i<3;i++){execute(t,3600000);realize(t);}check(events("Sea_MapTransitionDone")==0&&!core.erased,"mapReady and arbitrary elapsed cannot finish seaOnly");check(rs.colors.back()==0xffffffff,"mapReady cannot reveal seaOnly frame");check(rs.cameraSets==0&&rs.lookCameraSets==0&&rs.perspectiveSets==0,"no ascent while destination unprepared");check(storm_map_player::prepareCalls==0,"no map miniature preparation");
 const CVECTOR newShip{1000,5,-300};a.values["x"]=newShip.x;a.values["y"]=newShip.y;a.values["z"]=newShip.z;a.values["scenePrepared"]=1;execute(t,8000);check(rs.cameraSets==0,"scenePrepared is not consumed during Execute");rs.source.tag=91;realize(t);check(rs.cameraSets==1&&rs.lookCameraSets==0&&rs.perspectiveSets==0,"destination Realize restores camera directly");check(same(rs.position,oldPosition+newShip-oldShip)&&same(rs.angles,oldAngles)&&near(rs.fov,oldFov),"translated camera preserves angles and FOV");check(rs.colors.back()==0xffffffff&&rs.frameTags.back()==17,"first prepared destination retains opaque outgoing overlay");check(!SeaMapTransition::Loading()&&events("Sea_MapTransitionDone")==0,"prepared begins reveal without early Done");
 execute(t,150);realize(t);check((rs.colors.back()>>24)>0&&(rs.colors.back()>>24)<255,"reveal alpha progresses");check(events("Sea_MapTransitionDone")==0,"half reveal remains alive");execute(t,151);realize(t);check(events("Sea_MapTransitionDone")==1&&core.erased,"completed reveal emits one Done then erase");check(core.actions.size()==3&&core.actions[0]=="Sea_MapTransitionCommit"&&core.actions[1]=="Sea_MapTransitionDone"&&core.actions[2]=="erase","seaOnly terminal event order");std::cout<<"PASS seaOnly lifecycle, mapReady hold, translated camera, opaque-first-frame, reveal/event order\n";}
void captureFailures(){for(int step=1;step<=3;++step){VDX9RENDER rs;rs.failStep=step;reset(rs);auto a=attrs(true);SeaMapTransition t;t.AttributesPointer=&a;check(t.Init(),"capture failure Init");realize(t);check(core.actions.size()==2&&core.actions[0]=="Sea_DirectSailAbort"&&core.actions[1]=="erase","capture failure Abort before erase");check(events("Sea_MapTransitionCommit")==0&&!SeaMapTransition::Loading(),"capture failure prevents commit and captured state");check(rs.colors.empty(),"capture failure draws no unavailable frame");}std::cout<<"PASS capture failure at GetRenderTarget/CreateTexture/StretchRect: Abort before teardown, no commit\n";}
void manualNegative(){VDX9RENDER rs;reset(rs);auto a=attrs();storm_map_player::metricsAvailable=false;SeaMapTransition t;t.AttributesPointer=&a;check(!t.Init(),"manual Init rejects missing miniature metrics");check(storm_map_player::boundsCalls==1&&!SeaMapTransition::Active(),"manual metrics owner remains required");std::cout<<"PASS manual Init negative keeps miniature metric requirement\n";}
void manualForward(){VDX9RENDER rs;reset(rs);auto a=attrs();SeaMapTransition t;t.AttributesPointer=&a;check(t.Init(),"manual forward Init");check(storm_map_player::boundsCalls>0&&storm_map_player::visualCalls>0,"manual forward measures miniature/ship");execute(t,1250);check(rs.lookCameraSets==1&&rs.perspectiveSets==1,"manual forward ascent remains");realize(t);check(rs.captureCalls==1&&storm_map_player::prepareCalls==1,"manual forward apex capture and miniature prepare");execute(t,16);check(events("Sea_MapTransitionCommit")==1,"manual forward commits");execute(t,60000);realize(t);check(!core.erased&&rs.colors.back()==0xffffffff,"manual forward waits for mapReady");a.values["mapReady"]=1;execute(t,16);realize(t);check(rs.colors.back()==0xffffffff,"manual mapReady first reveal frame opaque");execute(t,301);realize(t);check(events("Sea_MapTransitionDone")==1&&core.erased,"manual mapReady reveals normally");std::cout<<"PASS manual forward camera/apex/mapReady lifecycle\n";}
void manualReverse(){VDX9RENDER rs;reset(rs);auto a=attrs(false,true);SeaMapTransition t;t.AttributesPointer=&a;check(t.Init(),"manual reverse Init");check(storm_map_player::boundsCalls==1&&storm_map_player::visualCalls==0,"manual reverse defers destination metrics");check(SeaMapTransition::OverrideMapCamera()&&rs.cameraSets==1,"manual reverse map tilt remains");execute(t,401);realize(t);check(rs.captureCalls==1,"manual reverse captures after tilt");execute(t,16);check(events("Wdm_SeaTransitionCommit")==1,"manual reverse commit owner remains");check(!SeaMapTransition::OverrideMapCamera(),"reverse override ends at commit");execute(t,10000);realize(t);check(!core.erased&&rs.colors.back()==0xffffffff,"manual reverse waits for scenePrepared");a.values["scenePrepared"]=1;realize(t);check(storm_map_player::visualCalls==1&&rs.colors.back()==0xffffffff,"manual reverse prepared sea frame metrics and opaque overlay");execute(t,1251);realize(t);check(events("Sea_MapTransitionDone")==1&&core.erased&&rs.lookCameraSets>0,"manual reverse descent and completion remain");std::cout<<"PASS manual reverse tilt/capture/prepared-scene/descent lifecycle\n";}
int main(){try{seaLifecycle();captureFailures();manualNegative();manualForward();manualReverse();std::cout<<"PASS "<<assertions<<" independent assertions; actual header used unchanged; CPU fake renderer only\n";}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<" (after "<<assertions<<" assertions)\n";return 1;}}
